#!/usr/bin/env bash
# xatodo → superlive v2 component package build script
#
# Output: dist/xatodo-component-<version>.zip
# Package structure (package root):
#   manifest.json          component manifest (generated by gen-manifest.py;
#                          files excludes itself)
#   config.toml            component-form config (relative sqlite path; the
#                          parent directory is created by the server at startup)
#   bin/xatodo-server      server release binary (unix executable bit kept)
#   ui/**                  full web build artifact (the shell maps it to the
#                          /comps/{id}/ static space)
#
# Contract references:
#   superlive/slsdk-rs/src/manifest.rs          manifest JSON shape and validate rules
#   superlive/shell/src-tauri/src/installer.rs  shell-side install checks
#                                                  (fingerprints/set difference/unix perm restore)
#   superlive/docs/architecture.md              installation and lifecycle
#
# Usage: scripts/package-component.sh (no args, one-shot: clean old artifacts
#        → full build (web+server) → assemble → manifest → zip → self-verify;
#        authorized actions such as npm install / cargo dependency fetch are
#        out of scope)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
SERVER_DIR="$ROOT/server"   # cargo workspace root (entity/migration/server crates)
WEB_DIR="$ROOT/web"

COMPONENT_ID="xatodo"
NAMESPACE="todo"
DISPLAY_NAME="待办"
BIN_NAME="xatodo-server"
MIN_SHELL_VERSION="0.1.0"
LAUNCH_COMMAND="./bin/${BIN_NAME}"

log() { echo "==> $*"; }
die() { echo "error: $*" >&2; exit 1; }

for tool in cargo npm zip python3; do
  command -v "$tool" >/dev/null 2>&1 || die "missing required command: $tool"
done

# ---- 0. Clean old artifacts (one-shot semantics: every run starts from a
# clean artifact state) ----
# dist/: clears all old versions of this component's zips (glob covers stale
# version numbers; only ${COMPONENT_ID}-component-*.zip of this component
# form is cleared, nothing else is touched); web/dist is fully cleared (no
# explicit outDir in web/vite.config, i.e. the default dist). The server
# target is not cleared: cargo incremental compilation guarantees correctness
# on its own, and a full clean is too costly — not done unless necessary.
log "Cleaning old artifacts: dist/${COMPONENT_ID}-component-*.zip + web/dist"
rm -f "$ROOT/dist/${COMPONENT_ID}-component-"*.zip
rm -rf "$WEB_DIR/dist"

# Identity same-source check (audit S2): the script-side id/namespace must
# match the consumers — the shell matches manifest.id against the id returned
# by the component's health; drift would only surface late as a runtime
# failure, so it is intercepted at packaging time.
# Difference from the sl-events version: the xatodo server side has no
# standalone NAMESPACE constant (the self-reported namespace is bound to
# COMPONENT_ID; see server/src/component.rs "COMPONENT_ID doubles as the
# registry dispatch key"; the misalignment between that self-reported value
# and manifest.namespace was adjudicated to stand as recorded). The runtime
# consumers of manifest.namespace are shell dispatch and the web prefix, so
# the NAMESPACE same-source check targets the web apiClient's
# NAMESPACE_PREFIX.
SERVER_CID="$(grep -oP 'COMPONENT_ID: &str = "\K[^"]+' "$SERVER_DIR/server/src/component.rs" || true)"
if [ -z "$SERVER_CID" ]; then
  die "failed to extract the COMPONENT_ID constant from server/src/component.rs"
fi
if [ "$SERVER_CID" != "$COMPONENT_ID" ]; then
  die "COMPONENT_ID drift: script=$COMPONENT_ID server constant=$SERVER_CID"
fi
WEB_NS_PREFIX="$(grep -oP "NAMESPACE_PREFIX = '/api/\\K[^']+" "$WEB_DIR/src/services/apiClient.ts" || true)"
if [ -z "$WEB_NS_PREFIX" ]; then
  die "failed to extract NAMESPACE_PREFIX from web/src/services/apiClient.ts"
fi
if [ "$WEB_NS_PREFIX" != "$NAMESPACE" ]; then
  die "NAMESPACE drift: script=$NAMESPACE web NAMESPACE_PREFIX=/api/$WEB_NS_PREFIX"
fi

# ---- 1. Component version (source of truth: workspace
# [workspace.package].version) ----
VERSION="$(awk '/^\[workspace\.package\]/{sec=1; next} /^\[/{sec=0} sec && /^version = /{gsub(/"/, "", $3); print $3; exit}' "$SERVER_DIR/Cargo.toml")"
[ -n "$VERSION" ] || die "failed to extract version from [workspace.package] in $SERVER_DIR/Cargo.toml"
log "Component version: $VERSION"

STAGING="$(mktemp -d)"
trap 'rm -rf "$STAGING"' EXIT
mkdir -p "$ROOT/dist"
ZIP_PATH="$ROOT/dist/${COMPONENT_ID}-component-${VERSION}.zip"

# ---- 2. server release build ----
log "Building server: cargo build --release -p xa-todo-server"
(cd "$SERVER_DIR" && cargo build --release -p xa-todo-server)
SERVER_BIN="$SERVER_DIR/target/release/${BIN_NAME}"
[ -f "$SERVER_BIN" ] || die "release binary missing: $SERVER_BIN"

# ---- 3. web build ----
log "Building web: npm run build (artifact web/dist)"
(cd "$WEB_DIR" && npm run build)
# Component build form contract (web/vite.config.js): the entry is the fixed
# name entry.js (rollupOptions.input is the sole src/entry.tsx +
# entryFileNames 'entry.js'), index.html is not part of the build artifact
[ -f "$WEB_DIR/dist/entry.js" ] || die "web build artifact incomplete: $WEB_DIR/dist/entry.js missing"

# ---- 4. Assemble the package directory ----
log "Assembling package directory (bin + ui + config.toml)"
mkdir -p "$STAGING/bin" "$STAGING/ui"
cp "$SERVER_BIN" "$STAGING/bin/${BIN_NAME}"
chmod 755 "$STAGING/bin/${BIN_NAME}"
cp -a "$WEB_DIR/dist/." "$STAGING/ui/"
cat > "$STAGING/config.toml" <<'EOF'
# xatodo component-form config (bundled in the package; launched by the
# superlive v2 shell)
# In component mode the listen address and auth are taken over by the shell
# (SL_ENDPOINT / token env vars injected); the listen and users sections are
# not consumed but stay as placeholders because deserialization requires the
# fields.
[server]
listen = "0.0.0.0:8600"
# Relative to the process working directory (the shell uses the component
# install directory as cwd); the data/ parent directory is created
# automatically by the server at startup
database_url = "sqlite://data/xatodo.db?mode=rwc"

[users]
entries = []
EOF

# ---- 5. Generate manifest.json (entry discovery + full file fingerprints) ----
log "Generating manifest.json"
python3 "$SCRIPT_DIR/gen-manifest.py" \
  --staging "$STAGING" \
  --id "$COMPONENT_ID" \
  --namespace "$NAMESPACE" \
  --display-name "$DISPLAY_NAME" \
  --version "$VERSION" \
  --min-shell-version "$MIN_SHELL_VERSION" \
  --launch-command "$LAUNCH_COMMAND"

# ---- 6. zip packaging (relative paths + unix permissions) ----
log "Packaging: $ZIP_PATH"
rm -f "$ZIP_PATH"   # zip updates existing archives; delete first to avoid stale entries
(cd "$STAGING" && zip -qr "$ZIP_PATH" manifest.json config.toml bin ui)

# ---- 7. Self-verification (simulates the shell-side install check chain) ----
log "Self-verifying the package (contract checks + set-difference consistency + fingerprint comparison)"
python3 "$SCRIPT_DIR/verify-package.py" "$ZIP_PATH"

# ---- 8. ns prefix proof (generalization of the module-9 contract-misalignment
# defense) ----
# The UI sends /api/{ns}/{rest} (the shell strips the ns segment for
# dispatch); service paths in the artifact must carry this component's ns
# prefix — a missing segment becomes a runtime 404 inside the shell (the
# sl-finance incident showed systematic absence invisible to tsc/build; the
# only reliable interception point is a packaging-time grep of the artifact)
# The check accepts both service-path shapes: the full string "/api/todo/xxx"
# and the base constant "/api/todo" + template concatenation (the ns segment
# followed by a slash or a closing quote both match; the regex anchors on
# quote + ns segment + boundary, naturally avoiding false matches like
# /api/todoX). grep -c reads all input without early exit, eliminating the
# grep -q early-exit SIGPIPE misfire against unzip under pipefail (exit 141)
NS_HITS=$(unzip -p "$ZIP_PATH" ui/entry.js | grep -c -E "[\"']/api/todo(/|[\"'])" || true)
if [ "${NS_HITS:-0}" -gt 0 ]; then
  log "ns prefix proof: artifact contains /api/todo paths (${NS_HITS} hits) ✓"
else
  die "ns prefix missing: artifact ui/entry.js has no /api/todo paths (guaranteed 404 inside the shell)"
fi

log "Packaging complete: $ZIP_PATH"
